/* Good Contrast */
body {
  background-color: #ffffff;
  color: #000000;
}
/* Bad Contrast */
body {
  background-color: #eeeeee;
  color: #cccccc;
}

body {
  font-family: Arial, sans-serif;
  font-size: 1rem;
  line-height: 1.6;
}

a:focus,
button:focus,
input:focus {
  outline: 2px solid orange;
}
